<script setup>
import { ref,onMounted } from 'vue'
import { recipeRequest as request,writeRecipeResource as save,removeRecipeResource as remove } from '../../api/recipes'
import { useRecipeAction } from './recipeUI'
const {busy,error,success,run}=useRecipeAction()
const foods=ref([]),terms=ref([]),rules=ref([]),termId=ref(null),ruleId=ref(null),pending=ref(null)
const term=ref({name:'',kind:'ingredient',aliases:''}),rule=ref({target:'food',target_id:'',rule_type:'like',notes:''})
const foodId=ref(''),composition=ref(null)
const labels={like:'喜欢',dislike:'不喜欢',allergy:'过敏',forbidden:'禁用'},statuses={unknown:'未知',partial:'不完整',declared_complete:'用户已核对完整'}
async function load(){const [a,b,c]=await Promise.all([request('/foods'),request('/ingredient-terms'),request('/food-preferences')]);foods.value=a.items;terms.value=b.items;rules.value=c.items}
function editTerm(t){termId.value=t.id;term.value={name:t.name,kind:t.kind,aliases:t.aliases.join('、')}}
async function submitTerm(){await run(async()=>{await save('/ingredient-terms',{...term.value,aliases:term.value.aliases.split(/[、,\n]/).map(x=>x.trim()).filter(Boolean)},termId.value);termId.value=null;term.value={name:'',kind:'ingredient',aliases:''};await load()},'规范术语已保存')}
function editRule(r){ruleId.value=r.id;rule.value={target:r.food_id?'food':'term',target_id:r.food_id||r.term_id,rule_type:r.rule_type,notes:r.notes}}
async function submitRule(){await run(async()=>{await save('/food-preferences',{food_id:rule.value.target==='food'?rule.value.target_id:null,term_id:rule.value.target==='term'?rule.value.target_id:null,rule_type:rule.value.rule_type,notes:rule.value.notes},ruleId.value);ruleId.value=null;rule.value={target:'food',target_id:'',rule_type:'like',notes:''};await load()},'规则已保存')}
async function loadComposition(){composition.value=null;if(foodId.value)await run(async()=>{composition.value=await request(`/foods/${foodId.value}/composition`)})}
// Composition is a singleton resource: its endpoint uses PUT, not the collection helper.
async function putComposition(){await run(async()=>{const c=composition.value;composition.value=await request(`/foods/${foodId.value}/composition`,{method:'PUT',body:JSON.stringify({ingredient_status:c.ingredient_status,allergen_status:c.allergen_status,assessed_food_updated_at:c.current_food_updated_at,source_note:c.source_note,terms:c.terms.map(t=>({term_id:t.term_id,relation:t.relation}))})})},'成分信息已保存')}
async function confirmDelete(){await run(async()=>{await remove(pending.value.path,pending.value.id);pending.value=null;await load()},'已删除')}
onMounted(()=>run(load))
</script>
<template><section><h2>成分、术语与饮食偏好</h2><p class="recipe-notice">过敏和禁用在评分前排除。食物规则只针对所选食物；跨食物限制请使用规范食材/过敏原术语，并维护食物成分映射。别名仅用于名称匹配，不推断过敏关系。</p>
<p v-if="error" role="alert" class="recipe-error">{{error}}</p><p v-if="success" role="status">{{success}}</p><p v-if="busy">正在处理…</p>
<details class="recipe-panel" open><summary>规范食材与别名管理</summary><form @submit.prevent="submitTerm"><fieldset :disabled="busy"><div class="recipe-row"><label>规范名称<input v-model="term.name" maxlength="100" required></label><label>类型<select v-model="term.kind"><option value="ingredient">食材</option><option value="allergen">过敏原</option></select></label><label>别名（顿号分隔）<input v-model="term.aliases"></label><button class="btn btn-primary">{{termId?'保存术语修改':'新增术语'}}</button><button v-if="termId" class="btn" type="button" @click="termId=null;term={name:'',kind:'ingredient',aliases:''}">取消编辑</button></div></fieldset></form>
<ul><li v-for="t in terms" :key="t.id">{{t.name}}（{{t.kind==='allergen'?'过敏原':'食材'}}）· {{t.aliases.join('、')||'无别名'}} <button class="btn" :disabled="busy" @click="editTerm(t)">编辑术语</button> <button class="btn" :disabled="busy" @click="pending={path:'/ingredient-terms',id:t.id,name:t.name}">删除术语</button></li></ul><p v-if="!terms.length">暂无规范术语，请按实际标签资料录入。</p></details>
<details class="recipe-panel"><summary>食物组成成分维护</summary><p class="recipe-note">完整状态代表用户核对声明，不是权威认证。请核对实际包装、配料及交叉接触提示；来源不明时保留未知。食物资料变更后需重新核对。</p>
<label>待核对食物<select v-model="foodId" :disabled="busy" @change="loadComposition"><option value="">请选择</option><option v-for="f in foods" :key="f.id" :value="f.id">{{f.name}}</option></select></label>
<form v-if="composition" @submit.prevent="putComposition"><fieldset :disabled="busy"><p v-if="composition.outdated" class="recipe-notice">尚未核对或旧核对已过期。保存前请重新核对当前食物资料。</p><div class="recipe-grid"><label>食材信息状态<select v-model="composition.ingredient_status"><option v-for="(v,k) in statuses" :key="k" :value="k">{{v}}</option></select></label><label>过敏原信息状态<select v-model="composition.allergen_status"><option v-for="(v,k) in statuses" :key="k" :value="k">{{v}}</option></select></label></div><label>核对依据与来源<textarea v-model="composition.source_note" maxlength="1000" placeholder="填写实际资料，不要猜测"></textarea></label>
<div v-for="(t,index) in composition.terms" :key="index" class="recipe-row"><label>成分术语<select v-model="t.term_id" required><option disabled value="">选择规范术语</option><option v-for="x in terms" :key="x.id" :value="x.id">{{x.name}}</option></select></label><label>关系<select v-model="t.relation"><option value="contains">含有</option><option value="may_contain">可能含有</option></select></label><button class="btn" type="button" @click="composition.terms.splice(index,1)">移除成分</button></div><div class="recipe-row"><button class="btn" type="button" @click="composition.terms.push({term_id:'',relation:'contains'})">添加成分</button><button class="btn btn-primary">确认核对并保存</button></div></fieldset></form></details>
<section class="recipe-panel"><h3>喜好、过敏及禁用规则</h3><form @submit.prevent="submitRule"><fieldset :disabled="busy"><div class="recipe-grid"><label>规则对象类型<select v-model="rule.target" @change="rule.target_id=''"><option value="food">具体食物</option><option value="term">规范食材或过敏原</option></select></label><label>规则对象<select v-model="rule.target_id" required><option disabled value="">请选择</option><option v-for="t in (rule.target==='food'?foods:terms)" :key="t.id" :value="t.id">{{t.name}}</option></select></label><label>规则<select v-model="rule.rule_type"><option v-for="(v,k) in labels" :key="k" :value="k">{{v}}</option></select></label><label>备注<input v-model="rule.notes" maxlength="1000"></label></div><div class="recipe-row"><button class="btn btn-primary">{{ruleId?'保存规则修改':'新增规则'}}</button><button v-if="ruleId" class="btn" type="button" @click="ruleId=null;rule={target:'food',target_id:'',rule_type:'like',notes:''}">取消编辑</button></div></fieldset></form>
<ul><li v-for="r in rules" :key="r.id">{{labels[r.rule_type]}}：{{r.target_name}} <span v-if="r.term_id">（规范术语）</span> · {{r.notes}} <button class="btn" :disabled="busy" @click="editRule(r)">编辑规则</button> <button class="btn" :disabled="busy" @click="pending={path:'/food-preferences',id:r.id,name:r.target_name}">删除规则</button></li></ul><p v-if="!rules.length">尚未设置任何喜好或禁忌规则。</p></section>
<div v-if="pending" role="alertdialog" aria-label="确认删除资源" class="recipe-notice">确定删除 {{pending.name}}？<button class="btn" :disabled="busy" @click="confirmDelete">确认删除</button><button class="btn" :disabled="busy" @click="pending=null">取消</button></div>
</section></template>
